<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>TechSeba Work Order - Rajon International</title>
<style>
  :root {
    --navy:#0b2c72;
    --blue:#0e6fe8;
    --purple:#7628d8;
    --light:#f5f8ff;
    --line:#cfd8ea;
    --text:#1b2430;
  }
  * { box-sizing: border-box; }
  body {
    margin:0;
    font-family: Arial, Helvetica, sans-serif;
    background:#e9edf5;
    color:var(--text);
  }
  .toolbar {
    position:sticky;
    top:0;
    z-index:10;
    display:flex;
    gap:10px;
    justify-content:center;
    padding:12px;
    background:#111827;
    box-shadow:0 2px 8px rgba(0,0,0,.2);
  }
  .toolbar button {
    border:0;
    border-radius:8px;
    padding:10px 18px;
    font-size:15px;
    font-weight:700;
    cursor:pointer;
  }
  .print-btn { background:#2563eb; color:#fff; }
  .reset-btn { background:#fff; color:#111827; }
  .page {
    width:210mm;
    min-height:297mm;
    margin:14px auto;
    background:#fff;
    padding:14mm 14mm 12mm;
    position:relative;
    box-shadow:0 0 18px rgba(0,0,0,.14);
    overflow:hidden;
    page-break-after:always;
  }
  .page:last-child { page-break-after:auto; }
  .top-line {
    position:absolute;
    top:0; left:0; right:0;
    height:7px;
    background:linear-gradient(90deg,var(--blue),var(--purple));
  }
  .header {
    display:flex;
    align-items:flex-start;
    justify-content:space-between;
    border-bottom:2px solid var(--navy);
    padding-bottom:10px;
    margin-bottom:12px;
  }
  .logo {
    width:290px;
    max-height:90px;
    object-fit:contain;
    object-position:left center;
  }
  .doc-title {
    text-align:right;
  }
  .doc-title h1 {
    margin:0;
    color:var(--navy);
    font-size:28px;
    letter-spacing:.5px;
  }
  .doc-title .meta {
    margin-top:8px;
    font-size:13px;
    line-height:1.8;
  }
  .editable {
    display:inline-block;
    min-width:110px;
    border-bottom:1px dotted #555;
    padding:1px 4px;
    outline:none;
  }
  .editable:focus {
    background:#fff8cc;
    border-bottom:1px solid #e0a800;
  }
  .section-title {
    display:inline-block;
    margin:8px 0 7px;
    padding:6px 14px;
    color:#fff;
    background:linear-gradient(90deg,var(--navy),var(--purple));
    font-size:14px;
    font-weight:700;
    clip-path:polygon(0 0,92% 0,100% 50%,92% 100%,0 100%);
  }
  .two-col {
    display:grid;
    grid-template-columns:1fr 1fr;
    gap:18px;
  }
  .info-box {
    border:1px solid var(--line);
    border-radius:8px;
    padding:10px 12px;
    background:var(--light);
    min-height:120px;
  }
  .info-box h3 {
    margin:0 0 7px;
    color:var(--navy);
    font-size:17px;
  }
  .info-line { margin:5px 0; font-size:13px; line-height:1.5; }
  .project-title {
    border-left:5px solid var(--purple);
    padding:9px 12px;
    background:#f8f6ff;
    font-weight:700;
    margin:3px 0 10px;
  }
  p, li { font-size:12.5px; line-height:1.5; }
  ul.scope {
    columns:2;
    column-gap:28px;
    margin:5px 0 10px;
    padding-left:20px;
  }
  ul.scope li { margin:3px 0; break-inside:avoid; }
  table {
    width:100%;
    border-collapse:collapse;
    margin:7px 0 12px;
    font-size:12.5px;
  }
  th {
    background:var(--navy);
    color:#fff;
    padding:8px;
    border:1px solid #27488b;
  }
  td {
    border:1px solid #b9c5d8;
    padding:8px;
    vertical-align:top;
  }
  .amount { text-align:right; font-weight:700; }
  .note {
    background:#fff8e8;
    border-left:4px solid #f59e0b;
    padding:8px 10px;
    font-size:12px;
  }
  .legal {
    display:grid;
    grid-template-columns:1.1fr 1fr;
    gap:12px;
    border:1px solid #b7c4de;
    padding:10px;
    background:#fafbff;
  }
  .legal strong { color:var(--navy); }
  .terms {
    margin:0;
    padding-left:20px;
  }
  .terms li { margin:4px 0; }
  .signatures {
    display:grid;
    grid-template-columns:1fr 1fr;
    gap:28px;
    margin-top:24px;
  }
  .sig-box {
    border:1px solid #aebbd0;
    min-height:145px;
    padding:12px;
  }
  .sig-title {
    color:var(--navy);
    font-weight:700;
    margin-bottom:18px;
  }
  .sig-line {
    margin:12px 0;
    border-bottom:1px solid #555;
    height:20px;
  }
  .footer {
    position:absolute;
    left:0; right:0; bottom:0;
    height:18mm;
    background:linear-gradient(90deg,var(--navy),#101b45);
    color:#fff;
    display:flex;
    align-items:center;
    justify-content:space-between;
    padding:0 14mm;
    font-size:11px;
  }
  .footer span { opacity:.95; }
  .page-no {
    font-weight:700;
    color:#e7dcff;
  }
  @media print {
    body { background:#fff; }
    .toolbar { display:none !important; }
    .page {
      margin:0;
      box-shadow:none;
      width:210mm;
      min-height:297mm;
    }
    .editable:focus { background:transparent; }
  }
</style>
</head>
<body>

<div class="toolbar">
  <button class="print-btn" onclick="window.print()">Print / Save as PDF</button>
  <button class="reset-btn" onclick="location.reload()">Reset Changes</button>
</div>

<section class="page">
  <div class="top-line"></div>
  <div class="header">
    <img src="data:image/png;base64," class="logo" alt="TechSeba Logo">
    <div class="doc-title">
      <h1>WORK ORDER</h1>
      <div class="meta">
        Work Order No: <span class="editable" contenteditable="true">TS/WO/POS/2026/001</span><br>
        Date: <span class="editable" contenteditable="true">27 July 2026</span>
