    </div>
  </div>

  <div class="two-col">
    <div class="info-box">
      <h3>FROM</h3>
      <div class="info-line"><strong>TechSeba</strong></div>
      <div class="info-line">Room #01 (4th Floor)</div>
      <div class="info-line">Star Hotel & Restaurant Building</div>
      <div class="info-line">49, Johnson Road, Kotowali</div>
      <div class="info-line">Dhaka-1100, Bangladesh</div>
      <div class="info-line">Website: techseba.com</div>
      <div class="info-line">Mobile: <span class="editable" contenteditable="true">01716-987654</span></div>
      <div class="info-line">Email: <span class="editable" contenteditable="true">info@techseba.com</span></div>
    </div>

    <div class="info-box">
      <h3>TO</h3>
      <div class="info-line"><strong>Rajon International</strong></div>
      <div class="info-line">Business Address: <span class="editable" contenteditable="true">Enter client address</span></div>
      <div class="info-line">Contact Person: <span class="editable" contenteditable="true">Enter name</span></div>
      <div class="info-line">Designation: <span class="editable" contenteditable="true">Enter designation</span></div>
      <div class="info-line">Mobile: <span class="editable" contenteditable="true">Enter mobile</span></div>
      <div class="info-line">Email: <span class="editable" contenteditable="true">Enter email</span></div>
